# Vendored from benchmark/initializers/macos/deltachat_snapshot.py.
"""Prepare DeltaChat for an episode.

DeltaChat keeps each account in a WAL-mode SQLite database below its profile
root.  Preparation reads every account database through a private copy -- the
wal-index a reader needs is not part of the shipped profile, and a copy keeps
the profile untouched -- and confirms the seeded source chats and their search
tokens are present, that the chats the task creates do not exist yet, that the
records the task sends are absent, and that the documents the instruction
attaches are on disk.  It sends nothing and creates nothing.
"""

from __future__ import annotations

import json
from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: DeltaChat's profile root, relative to the guest home directory.
DEFAULT_PROFILE_ROOT = "~/Library/Application Support/DeltaChat"


class DeltaChatSnapshotInitializer(MacAppInitializer):
    """Confirm the DeltaChat starting point an episode assumes."""

    INITIALIZER_ID = "initializers.macos.deltachat_snapshot:DeltaChatSnapshotInitializer"
    APP_NAME = "DeltaChat"
    BUNDLE_ID = "chat.delta.desktop.electron"
    SETTLE_MS = 5000

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        profile_root = str(params.get("profile_root") or DEFAULT_PROFILE_ROOT)
        script = "\n".join(
            [
                "import json",
                "import pathlib",
                "import shutil",
                "import sqlite3",
                "import tempfile",
                "",
                f"root = pathlib.Path({profile_root!r}).expanduser()",
                "def open_snapshot(db_path):",
                "    work = pathlib.Path(tempfile.mkdtemp(prefix='deltachat-init-'))",
                "    for suffix in ('', '-wal', '-shm'):",
                "        source = pathlib.Path(str(db_path) + suffix)",
                "        if source.is_file():",
                "            shutil.copy2(str(source), str(work / (db_path.name + suffix)))",
                "    connection = sqlite3.connect(str(work / db_path.name))",
                "    connection.row_factory = sqlite3.Row",
                "    connection.execute('PRAGMA query_only=ON')",
                "    return connection, work",
                "",
                "accounts = []",
                "errors = []",
                "paths = sorted(root.rglob('dc.db')) if root.is_dir() else []",
                "for db_path in paths:",
                "    connection = None",
                "    work = None",
                "    try:",
                "        connection, work = open_snapshot(db_path)",
                "        chats = {}",
                "        for row in connection.execute('SELECT id, name FROM chats'):",
                "            name = str(row['name'] or '')",
                "            texts = [str(m['txt'] or '') for m in connection.execute(",
                "                'SELECT txt FROM msgs WHERE chat_id=? AND COALESCE(hidden,0)=0', (int(row['id']),))]",
                "            chats.setdefault(name, []).extend(texts)",
                "        accounts.append({'db_path': str(db_path), 'chats': chats})",
                "    except Exception as exc:",
                "        errors.append({'db_path': str(db_path), 'error': '%s: %s' % (type(exc).__name__, exc)})",
                "    finally:",
                "        if connection is not None:",
                "            connection.close()",
                "        if work is not None:",
                "            shutil.rmtree(str(work), ignore_errors=True)",
                "print(json.dumps({'profile_root': str(root), 'accounts': accounts, 'errors': errors}, ensure_ascii=False))",
            ]
        )
        evidence = self._guest_json(controller, script, what="the DeltaChat account databases")
        accounts = list(evidence.get("accounts") or [])
        if not accounts:
            detail = "; ".join(
                f"{item.get('db_path')}: {item.get('error')}" for item in evidence.get("errors") or []
            )
            raise InitializationError(
                f"no readable DeltaChat account database was found under {evidence.get('profile_root')}"
                + (f" ({detail})" if detail else "")
            )

        chats: dict[str, list[str]] = {}
        for account in accounts:
            for name, texts in dict(account.get("chats") or {}).items():
                chats.setdefault(name, []).extend(str(text) for text in texts)

        for source in params.get("required_sources") or []:
            chat_name = str((source or {}).get("chat_name") or "")
            token = str((source or {}).get("search_token") or "")
            if chat_name not in chats:
                raise InitializationError(
                    f"DeltaChat carries no seeded {chat_name} chat"
                )
            if token and not any(token in text for text in chats[chat_name]):
                raise InitializationError(
                    f"the seeded {chat_name} chat carries no message containing {token!r}"
                )

        forbidden_chats = [
            str(name) for name in (params.get("forbidden_chat_names") or []) if str(name)
        ]
        already = [name for name in forbidden_chats if name in chats]
        if already:
            raise InitializationError(
                "DeltaChat already carries the target chat(s) " + ", ".join(already)
            )

        for record in params.get("forbidden_self_messages") or []:
            chat_name = str((record or {}).get("chat_name") or "")
            text = str((record or {}).get("text") or "")
            if text and any(text in observed for observed in chats.get(chat_name, [])):
                raise InitializationError(
                    f"{chat_name} already carries the target record {text!r}"
                )

        documents = self._check_documents(controller, params.get("required_files"))
        return (
            f"DeltaChat carries {len(accounts)} account database(s) with the seeded source chats, "
            f"no target chats or records"
            + (f", and the {documents} attached document(s) on disk" if documents else "")
        )

    def _check_documents(self, controller: Any, paths: Any) -> int:
        """Confirm the documents the instruction attaches are on disk."""
        wanted = [str(path) for path in (paths or []) if str(path)]
        if not wanted:
            return 0
        script = "\n".join(
            [
                "import json",
                "from pathlib import Path",
                f"wanted = {json.dumps(wanted)}",
                "observed = [{'path': p, 'exists': Path(p).expanduser().is_file()} for p in wanted]",
                "print(json.dumps(observed))",
            ]
        )
        observed = self._guest_json(controller, script, what="the attached documents")
        missing = [item["path"] for item in observed if not item.get("exists")]
        if missing:
            raise InitializationError(
                "the documents the instruction attaches are missing: " + ", ".join(missing)
            )
        return len(observed)
